def chunk_list(lst: list, size: int) -> list[list]:
    if size <= 0:
        raise ValueError("size must be greater than 0")

    return [lst[i:i+size] for i in range(0, len(lst), size)]

def validate_ipv4(s: str) -> bool:
    # Split the input string into four parts based on '.'
    parts = s.split('.')

    # Check if there are exactly four parts
    if len(parts) != 4:
        return False

    # Iterate through each part to check its validity
    for part in parts:
        # Ensure the part is a non-empty digit and within the range 0-255
        if not part or not part.isdigit() or int(part) < 0 or int(part) > 255 or (part[0] == '0' and len(part) > 1):
            return False

    # If all checks pass, the string is a valid dotted IPv4 address
    return True

def factorial(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return 1 if n == 0 else n * factorial(n - 1)

def run_length_encode(s: str) -> str:
    if not s:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            encoded.append(str(count))
            encoded.append(s[i-1])
            count = 1

    # Append the last run
    encoded.append(str(count))
    encoded.append(s[-1])

    return ''.join(encoded)

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Create a copy of the intervals to avoid modifying the original list
    intervals_copy = intervals.copy()

    # Sort intervals by their start time
    intervals_copy.sort(key=lambda x: x[0])

    merged = []
    for interval in intervals_copy:
        if not merged or interval[0] > merged[-1][1]:
            # Add non-overlapping interval to the result
            merged.append(interval)
        else:
            # Merge overlapping intervals
            merged[-1][1] = max(merged[-1][1], interval[1])

    return merged
